    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        grid[x][y] = value

    dp = [[0] * N for _ in range(N)]
    for x in range(N):
        dp[x][0] = grid[x][0]
    for y in range(N):
        dp[0][y] = grid[0][y]

    for x in range(1, N):
        for y in range(1, N):
