def cantor_numbering(N: int) -> str:
    if N <= 0:
        return "0/1"
    else:
        n = N - 1
        k = (n + 2) // 3
        m = n - k * 3
        return str(1 + 3 * k + 2 * m) + "/" + str(3 ** (k + 1))

