def max_product(num_str, N, K):
    if K == 0:
        return int(num_str)

    dp = [[0] * (N + 1) for _ in range(K + 1)]

    for i in range(1, N + 1):
        dp[0][i] = int(num_str[:i])

    for j in range(1, K + 1):
        for i in range(1, N + 1):
            if j == 1:
                dp[j][i] = max(dp[j - 1][i - 1] * int(num_str[i - 1]), dp[j][i - 1])
            else:
                dp[j][i] = max(dp[j - 1][i - 1] * int(num_str[i - 1]), dp[j][i - 1], dp[j - 1][i - 2] * int(num_str[i - 2]))

    return dp[K][N]

