def count_partitions(n, k, x):
    # Create a 2D array to store the results
    dp = [[0] * (k + 1) for _ in range(x + 1)]

    # Base case: when n is 0, there is only one way to partition it: []
    for i in range(x + 1):
        dp[i][0] = 1

    # Populate the table
    for i in range(x + 1):
        for j in range(1, k + 1):
            # If i is less than j, then there are no ways to partition i into j parts
            if i < j:
                dp[i][j] = 0
            # If i is equal to j, then there is only one way to partition i into j parts: [i]
            elif i == j:
                dp[i][j] = 1
            # Otherwise, partition i into j parts by iterating over the possible values of the first part
            else:
                dp[i][j] = sum(dp[i - val][j - 1] for val in range(x + 1))

    # Return the result for the given n, k, and x
    return dp[n][k]

