def calculate_score(system: int, points: str) -> list:
    """
    Calculate the score of a series of ping-pong games based on the provided scoring system.

    Args:
        system (int): The number of points required to win a game (either 11 or 21).
        points (str): A string of 'W' and 'L' characters denoting points won by the player and opponent.

    Returns:
        list: A list of strings representing the score of each game.
    """
    game_scores = []
    current_score = 0
    opponent_score = 0
    for i in range(len(points)):
        point = points[i]
        if point == "W":
            current_score += 1
        else:
            opponent_score += 1
        if system == 11 and current_score == 10:
            if opponent_score == 10:
                game_scores.append(f"{current_score}:{opponent_score}")
            elif opponent_score == 9:
                game_scores.append(f"{current_score}:{opponent_score + 1}")
        elif system == 21 and current_score == 20:
            if opponent_score == 20:
                game_scores.append(f"{current_score}:{opponent_score}")
            elif opponent_score == 19:
                game_scores.append(f"{current_score}:{opponent_score + 1}")
        if current_score - opponent_score >= 2:
            break
    if current_score > 0 and opponent_score > 0:
        game_scores.append(f"{current_score}:{opponent_score}")
    return game_scores

