    # Find the index of the first element that is smaller than the number following it
    smaller_index = -1
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            smaller_index = i
            break

    # If no such element is found, it is the last permutation
    if smaller_index == -1:
        return False

    # Swap the first smaller element with the smallest number that is larger and comes after it
    for i in range(smaller_index + 1, len(perm)):
        if perm[i] > perm[smaller_index]:
            perm[smaller_index], perm[i] = perm[i], perm[smaller_index]
            break

    # Reverse the order of the numbers after the original first smaller number
    perm[smaller_index + 1:] = perm[smaller_index + 1:][::-1]

    return True

