def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 1:
        return 0
    left = [0] * n
    right = [0] * n
    for i in range(1, n):
        left[i] = left[i - 1] + (heights[i] < heights[i - 1])
        right[n - i - 1] = right[n - i] + (heights[n - i - 1] < heights[n - i])
    result = n
    for i in range(n - 1):
        result = min(result, left[i] + right[i + 1])
    return result

